import{_ as l,o,c as e,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Rook - Running Ceph Using Kubernetes - Alexander Trost & Kim-Norman Sahm, Cloudibility UG","description":"","frontmatter":{"title":"Rook - Running Ceph Using Kubernetes - Alexander Trost & Kim-Norman Sahm, Cloudibility UG","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","Kubernetes","Rook","容器化存储","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Rook_-_Running_Ceph_Using_Kubernetes_-_Alexander_Trost_Kim-Norman_Sahm_Cloudibility_UG.md","filePath":"posts/2019/Rook_-_Running_Ceph_Using_Kubernetes_-_Alexander_Trost_Kim-Norman_Sahm_Cloudibility_UG.md","lastUpdated":1780459816000}'),t={name:"posts/2019/Rook_-_Running_Ceph_Using_Kubernetes_-_Alexander_Trost_Kim-Norman_Sahm_Cloudibility_UG.md"};function r(n,i,s,h,d,u){return o(),e("div",null,[...i[0]||(i[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>（请在此处填写会议时间）</p><h4 id="会议地点" tabindex="-1">会议地点： <a class="header-anchor" href="#会议地点" aria-label="Permalink to &quot;会议地点：&quot;">​</a></h4><p>（请在此处填写会议地点）</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><ul><li>Alexander（Rook项目成员）</li><li>同事（因身体原因未能出席）</li><li>Sir Sir（Rook项目的吉祥物）</li><li>其他参会人员</li></ul><h4 id="会议议程" tabindex="-1">会议议程： <a class="header-anchor" href="#会议议程" aria-label="Permalink to &quot;会议议程：&quot;">​</a></h4><ol><li><strong>Rook项目介绍</strong></li><li><strong>Rook与Ceph的集成</strong></li><li><strong>Rook的架构</strong></li><li><strong>Rook的部署与配置</strong></li><li><strong>Rook的社区参与</strong></li><li><strong>问答环节</strong></li></ol><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><p><strong>1. Rook项目介绍</strong></p><p>Rook是一个开源项目，旨在帮助企业将Ceph等存储系统容器化，并在Kubernetes中进行部署和管理。Rook的目标是提供与Kubernetes的原生集成，使得用户能够轻松地部署、配置和管理Ceph集群。</p><p><strong>2. Rook与Ceph的集成</strong></p><p>Rook支持将Ceph作为存储后端进行部署和管理。除了Ceph之外，Rook还可以支持其他存储后端，例如Cassandra、HDFS等。</p><p><strong>3. Rook的架构</strong></p><p>Rook的架构主要包括以下组件：</p><ul><li><strong>Rook Operator</strong>：负责管理Ceph集群的生命周期，包括创建、删除、升级和故障转移等操作。</li><li><strong>Rook Discovery Agent</strong>：负责发现节点上的存储设备，并将其信息传递给Rook Operator。</li><li><strong>Ceph组件</strong>：包括Monitors、OSDs、MDS等。</li><li><strong>Kubernetes API</strong>：用于与Kubernetes集群进行交互。</li></ul><p><strong>4. Rook的部署与配置</strong></p><p>Rook提供了丰富的配置选项，允许用户根据需求进行定制。例如，用户可以指定要使用的节点、存储设备、网络配置等。</p><p><strong>5. Rook的社区参与</strong></p><p>Rook社区非常活跃，许多社区成员为Rook的开发和改进做出了贡献。Rook项目也积极参与开源社区，与其他开源项目进行合作。</p><p><strong>6. 问答环节</strong></p><p>会议的最后是问答环节，参会者就Rook的部署、配置、性能等方面提出了问题，Alexander和社区成员进行了详细的解答。</p><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>Rook项目将继续完善与Ceph的集成，并支持更多存储后端。</li><li>Rook项目将加强社区建设，吸引更多开发者参与。</li><li>Rook项目将关注用户反馈，不断改进产品。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>Rook项目团队将继续开发Rook，并发布新的版本。</li><li>Rook社区将持续开展活动，促进社区成员之间的交流。</li><li>Rook项目将积极与其他开源项目合作，共同推动开源生态的发展。</li></ul><h4 id="关键词" tabindex="-1">关键词： <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词：&quot;">​</a></h4><ul><li>Rook</li><li>Ceph</li><li>Kubernetes</li><li>Operator</li><li>CSI</li><li>Container Storage Interface</li><li>CRUSH algorithm</li><li>high availability</li><li>scalability</li><li>object storage</li><li>block storage</li><li>file system storage</li><li>consistency</li><li>decentralization</li><li>performance</li><li>bluestore</li><li>bluefs</li><li>rocksdb</li><li>OSD</li><li>MON</li><li>MDS</li><li>PG</li><li>RADOS</li><li>librados</li><li>libcephfs</li><li>cephfs</li><li>rbd</li><li>radosgw</li><li>RGW</li><li>RESTful API</li><li>authentication</li><li>authorization</li><li>encryption</li><li>erasure coding</li><li>replication</li><li>snapshots</li><li>clones</li><li>thin provisioning</li><li>iSCSI</li><li>Fibre Channel</li><li>NFS</li><li>CIFS</li><li>POSIX</li><li>monitoring</li><li>dashboard</li><li>management</li><li>orchestration</li><li>automation</li><li>integration</li><li>containerization</li><li>Kubernetes</li><li>Docker</li><li>virtualization</li><li>cloud computing</li><li>AWS</li><li>Azure</li><li>Google Cloud</li><li>hybrid cloud</li><li>multi-cloud</li><li>storage cluster</li><li>node</li><li>disk</li><li>SSD</li><li>HDD</li><li>JBOD</li><li>SAN</li><li>NAS</li><li>network</li><li>topology</li><li>failure domain</li><li>recovery</li><li>resilience</li><li>load balancing</li><li>caching</li><li>compression</li><li>deduplication</li><li>tiering</li><li>performance tuning</li><li>benchmarking</li><li>testing</li><li>validation</li></ul>',29)])])}const _=l(t,[["render",r]]);export{g as __pageData,_ as default};
